codeExamples.code:
import { ApiCheck, AssertionBuilder, Frequency } from '@checkly/cli/constructs';

new ApiCheck('orders-api-health', {
  name: 'Orders API — health endpoint',
  activated: true,
  muted: false,
  frequency: Frequency.EVERY_5M,
  locations: ['us-east-1', 'eu-west-1'],
  tags: ['api', 'production'],
  request: {
    url: 'https://api.example.com/v1/health',
    method: 'GET',
    followRedirects: true,
    timeout: 10_000,
    assertions: [
      AssertionBuilder.statusCode().equals(200),
      AssertionBuilder.responseTime().lessThan(2000),
      AssertionBuilder.jsonBody('$.status').equals('ok'),
    ],
  },
  retryStrategy: {
    type: 'LINEAR',
    baseBackoffSeconds: 60,
    maxRetries: 2,
    maxDurationSeconds: 600,
  },
  alertChannels: [],
});

import { BrowserCheck, Frequency } from '@checkly/cli/constructs';
import * as path from 'path';

new BrowserCheck('checkout-flow', {
  name: 'Checkout flow — add to cart and proceed',
  activated: true,
  frequency: Frequency.EVERY_10M,
  locations: ['us-east-1', 'eu-central-1'],
  tags: ['browser', 'critical-path'],
  code: {
    entrypoint: path.join(__dirname, 'checkout.spec.ts'),
  },
  retryStrategy: {
    type: 'EXPONENTIAL',
    baseBackoffSeconds: 30,
    maxRetries: 2,
    maxDurationSeconds: 300,
  },
});

